import React, { useState } from 'react';
import './History.css';

function History() {
  const [history] = useState([
    {
      id: 1,
      date: '10/01/2025',
      accountName: 'Account Demo 1',
      amount: 50000,
      status: 'Hoàn thành',
      icon: '✅'
    },
    {
      id: 2,
      date: '09/01/2025',
      accountName: 'Account Demo 2',
      amount: 100000,
      status: 'Đang xử lí',
      icon: '⏳'
    },
    {
      id: 3,
      date: '08/01/2025',
      accountName: 'Account Demo 3',
      amount: 200000,
      status: 'Hoàn thành',
      icon: '✅'
    },
  ]);

  return (
    <div className="history-container">
      <h1>📋 LỊCH SỬ MUA NICK</h1>

      {history.length === 0 ? (
        <div className="empty-state">
          <p>Bạn chưa mua nick nào. <a href="/products">Mua ngay</a></p>
        </div>
      ) : (
        <div className="history-table">
          <div className="table-header">
            <div className="col-date">Ngày Mua</div>
            <div className="col-account">Tên Acc</div>
            <div className="col-amount">Giá</div>
            <div className="col-status">Trạng Thái</div>
            <div className="col-action">Hành Động</div>
          </div>

          {history.map(item => (
            <div key={item.id} className={`table-row status-${item.status.replace(/\s+/g, '')}`}>
              <div className="col-date">{item.date}</div>
              <div className="col-account">{item.accountName}</div>
              <div className="col-amount">{item.amount.toLocaleString('vi-VN')} đ</div>
              <div className="col-status">
                <span className="status-badge">
                  {item.icon} {item.status}
                </span>
              </div>
              <div className="col-action">
                <button className="btn-detail">Chi Tiết</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default History;
